-use bcrypt::{hash, verify, DEFAULT_COST};
+use argon2::{Algorithm, Argon2, Params, Version};
+use argon2::password_hash::{SaltString, rand_core::OsRng};
+const PARAMS: (u32, u32, u32) = (64 * 1024, 3, 1); // memory KiB, iterations, lanes
+pub fn hash_new(pw: &str) -> Result<String> {
+    hash_argon2(pw)
+}
+fn hash_argon2(pw: &str) -> Result<String> {
+    let (m, t, p) = PARAMS;
+    let a = Argon2::new(Algorithm::Argon2id, Version::V0x13, Params::new(m, t, p, None)?);
+    Ok(a.hash_password(pw.as_bytes(), &SaltString::generate(&mut OsRng))?.to_string())
+}
+pub fn verify_and_upgrade(pw: &str, stored: &str) -> Result<Option<String>> {
+    if stored.starts_with("$2") {
+        if bcrypt::verify(pw, stored)? { return Ok(Some(hash_argon2(pw)?)); }
+        return Err(Error::BadPassword);
+    }
+    if !verify_argon2(pw, stored)? { return Err(Error::BadPassword); }
+    Ok(None)
+}

