+export async function refresh(oldToken: string): Promise<TokenPair> {
+  const row = await db.refreshTokens.findByHash(hash(oldToken));
+  if (!row) throw new AuthError('unknown refresh token');
+  if (row.revokedAt) {
+    await db.refreshTokens.revokeFamily(row.familyId);
+    throw new AuthError('refresh token reused');
+  }
+  await db.refreshTokens.revoke(row.id);
+  return issuePair(row.userId, row.familyId);
+}

